/**
 * Embedded template payloads.
 *
 * Paste the base64-encoded ZIP bytes for each template variant below (between
 * the backticks). Leave a constant as an empty string until you have the
 * payload for it — the generator will show a clear error in the UI if someone
 * tries to generate a wrapper for a variant that hasn't been configured yet,
 * instead of failing silently or producing a broken archive.
 *
 * How to get the base64 for a template zip (from a terminal):
 *   base64 -w 0 MyTemplate.zip > MyTemplate.b64.txt
 * then paste the contents of MyTemplate.b64.txt into the matching constant.
 */

// Third-party generic routing wrapper — default/current template.
export const THIRDPARTY_STANDARD_BASE64 = ``;

// Third-party generic routing wrapper — CCSID variant (future template).
export const THIRDPARTY_CCSID_BASE64 = ``;

// Bank wrapper — Normal version.
export const BANK_NORMAL_BASE64 = ``;

// Bank wrapper — TH version.
export const BANK_TH_BASE64 = ``;

// Bank wrapper — BTH version.
export const BANK_BTH_BASE64 = ``;
